const items = Array.isArray($input.first().json) ? $input.first().json : ($input.first().json.items || []);
console.log(`[Lead Finder] Crunchbase returned ${items.length} raw results`);

function pickName(it) { return it.full_name || it.person_name || it.name || `${it.first_name || ''} ${it.last_name || ''}`.trim() || null; }
function pickCompany(it) { return it.primary_organization_name || it.primary_organization || it.organization || it.company || null; }
function pickDomain(it) {
  const url = it.website || it.domain || it.organization_website || it.primary_organization_website || '';
  if (!url) return null;
  try { return new URL(url.startsWith('http') ? url : `https://${url}`).hostname.replace(/^www\./, ''); }
  catch { return url.replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0]; }
}
function splitName(full) {
  if (!full) return { first: '', last: '' };
  const parts = full.trim().split(/\s+/);
  return { first: parts[0] || '', last: parts.slice(1).join(' ') || '' };
}

const leads = items.map(it => {
  const full = pickName(it);
  const { first, last } = splitName(full);
  return {
    json: {
      full_name: full,
      first_name: first,
      last_name: last,
      company: pickCompany(it),
      domain: pickDomain(it),
      categories: (it.categories || it.investor_categories || []).join(', '),
      crunchbase_url: it.url || it.crunchbase_url || '',
      raw: it
    }
  };
}).filter(r => r.json.full_name && r.json.domain);

console.log(`[Lead Finder] ${leads.length} leads have name + domain`);
return leads;

const lead = $('Per Lead').item.json;
const hunterData = ($json.data || {});
const email = hunterData.email || null;
const score = Number(hunterData.score || 0);
const threshold = Number($env.HUNTER_MIN_CONFIDENCE || 0.9);
const minScore = threshold <= 1 ? threshold * 100 : threshold;

if (!email || score < minScore) {
  console.log(`[Lead Finder] SKIP ${lead.full_name}: ${!email ? 'no email found' : `score ${score} < ${minScore}`}`);
  return [];
}

console.log(`[Lead Finder] QUALIFIED ${lead.full_name}: ${email} (score=${score})`);
return [{ json: {
  full_name: lead.full_name,
  company: lead.company || 'Independent',
  email,
  confidence: score,
  categories: lead.categories,
  crunchbase_url: lead.crunchbase_url,
  domain: lead.domain
}}];

